#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
int outcomes=6;
int countA=0,countB=0,countBoth=0;
for(int die=1;die<=outcomes;die++){
    bool A=die%2==0,B=die>=4;
    countA+=A;countB+=B;countBoth+=(A&&B);
}
if(countB==0)return 1;
double conditional=double(countBoth)/countB;
cout<<"P(A) "<<double(countA)/outcomes
    <<" P(B) "<<double(countB)/outcomes<<" P(A|B) "<<conditional<<endl;
    return 0;
}

