#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
vector<double> target={2,3,5,8},prediction={1,1,1,1};
double learningRate=0.2;
vector<double> pseudoResidual(target.size(),0);
for(int i=0;i<int(target.size());i++)
    pseudoResidual[i]=target[i]-prediction[i];
for(int i=0;i<int(target.size());i++)
    prediction[i]+=learningRate*pseudoResidual[i];
double mse=0;
for(int i=0;i<int(target.size());i++)
    mse+=pow(target[i]-prediction[i],2)/target.size();
cout<<"Updated MSE "<<mse<<endl;
    return 0;
}

