#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
double x=1.5,weights[2]={0.4,0.6},mean[2]={0,2},sigma[2]={1,0.5};
double components[2];
for(int k=0;k<2;k++){
    double z=(x-mean[k])/sigma[k];
    components[k]=log(weights[k])-log(sigma[k]*sqrt(2*acos(-1.0)))-z*z/2;
}
double peak=max(components[0],components[1]);
double logMixture=peak+log(exp(components[0]-peak)+exp(components[1]-peak));
cout<<"Mixture density "<<exp(logMixture)<<endl;
    return 0;
}

