#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
vector<vector<double>> cachedKey={{1,0},{0,1},{1,1}};
vector<double> cachedValue={2,4,5},newQuery={1,1};
double maximum=-1e100;
vector<double> score(cachedKey.size(),0);
for(int t=0;t<int(cachedKey.size());t++){
    for(int j=0;j<2;j++)score[t]+=newQuery[j]*cachedKey[t][j];
    score[t]/=sqrt(2.0);
    maximum=max(maximum,score[t]);
}
double numerator=0,denominator=0;
for(int t=0;t<int(score.size());t++){
    double weight=exp(score[t]-maximum);
    numerator+=weight*cachedValue[t];
    denominator+=weight;
}
cout<<"Attention output "<<numerator/denominator<<endl;
    return 0;
}

