#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iomanip>
using namespace std;

int main(){
double varA=0.04,varB=0.01;
for(double cov:{0.0,0.005,0.009}){
    double denominator=varA+varB-2*cov;
    if(denominator<=0)return 1;
    double weightA=(varB-cov)/denominator;
    weightA=max(0.0,min(1.0,weightA));
    double weightB=1-weightA;
    double variance=weightA*weightA*varA+weightB*weightB*varB
        +2*weightA*weightB*cov;
    cout<<"Cov "<<cov<<" A "<<weightA<<" B "<<weightB
        <<" portfolio variance "<<variance<<endl;
}
    return 0;
}
